          [trim((string)$_POST['h1']) ?: $c['title'], sanitize_html((string)$_POST['intro']), sanitize_html((string)$_POST['body']), trim((string)$_POST['seo_title']), trim((string)$_POST['meta_desc']),
           trim((string)$_POST['primary_kw']), isset($_POST['seo_index']) ? 1 : 0, $c['path']]);
