/* ------------------------------------------------------------------ reviews */
function review_photo_upload(): ?string {
    if (empty($_FILES['photo']) || $_FILES['photo']['error'] === UPLOAD_ERR_NO_FILE) return null;
    $f = $_FILES['photo'];
    if ($f['error'] !== UPLOAD_ERR_OK || $f['size'] > 8 * 1024 * 1024) { flash('The photo was not saved: use a JPG, PNG or WebP under 8 MB.'); return null; }
    $info = @getimagesize($f['tmp_name']);
    $ext = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'][$info['mime'] ?? ''] ?? null;
    if (!$ext) { flash('The photo was not saved: use a JPG, PNG or WebP image.'); return null; }
    $dir = ROOT . '/uploads/reviews';
    if (!is_dir($dir)) mkdir($dir, 0775, true);
    $name = 'review-' . date('Ymd') . '-' . bin2hex(random_bytes(4)) . '.' . $ext;
    move_uploaded_file($f['tmp_name'], "$dir/$name");
    return "uploads/reviews/$name";
}
function admin_reviews(): void {
    if (is_post()) {
        $id = (int)($_POST['id'] ?? 0); $do = (string)($_POST['do'] ?? '');
        if ($do === 'delete') { $r = one('SELECT photo FROM reviews WHERE id = ?', [$id]); if ($r && $r['photo']) @unlink(ROOT . '/' . $r['photo']); q('DELETE FROM reviews WHERE id = ?', [$id]); flash('Review deleted.'); }
        if ($do === 'toggle') { q('UPDATE reviews SET published = 1 - published WHERE id = ?', [$id]); flash('Review updated.'); }
        if ($do === 'feature') { q('UPDATE reviews SET featured = 1 - featured WHERE id = ?', [$id]); flash('Review updated.'); }
        redirect('/admin/reviews');
    }
    $rows = all('SELECT r.*, p.title ptitle, p.handle FROM reviews r LEFT JOIN products p ON p.id = r.product_id ORDER BY r.review_date DESC, r.id DESC');
    $avg = $rows ? round(array_sum(array_column(array_filter($rows, fn($r) => $r['published']), 'rating')) / max(1, count(array_filter($rows, fn($r) => $r['published']))), 1) : 0;
    ob_start(); ?>
