      <p><?= h($o['name']) ?><?= $o['company'] ? '<br>' . h($o['company']) : '' ?><br><?= h($o['address1']) ?><?= $o['address2'] ? '<br>' . h($o['address2']) : '' ?><br><?= h(trim($o['city'] . ' ' . $o['region'] . ' ' . $o['postcode'])) ?><br><?= h($o['country']) ?></p>
