(() => {
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];

  // select all rows
  $$('[data-checkall]').forEach(c => c.addEventListener('change', () => $$('input[name="ids[]"]', c.closest('form')).forEach(x => (x.checked = c.checked))));
  $$('[data-bulk]').forEach(f => f.addEventListener('submit', e => {
    const a = f.querySelector('[name=action]').value, n = $$('input[name="ids[]"]:checked', f).length;
    if (a === 'delete' && !confirm(`Delete ${n} products for good? This cannot be undone.`)) e.preventDefault();
  }));

  // character counters for Google title / description
  $$('[data-count]').forEach(inp => {
    const max = +inp.dataset.count, out = $(`[data-count-for="${inp.name}"]`);
    const upd = () => { if (!out) return; const n = inp.value.length || (inp.placeholder || '').length; out.textContent = `${n}/${max}`; out.style.color = n > max ? '#B5291F' : ''; };
    inp.addEventListener('input', upd); upd();
  });
  // live Google preview
  const st = $('[name=seo_title]'), md = $('[name=meta_desc]');
  if (st && $('[data-serp-title]')) st.addEventListener('input', () => ($('[data-serp-title]').textContent = st.value || st.placeholder));
  if (md && $('[data-serp-desc]')) md.addEventListener('input', () => ($('[data-serp-desc]').textContent = md.value));

  // simple rich text editor
  $$('[data-editor]').forEach(ed => {
    const area = $('.area', ed), ta = $('textarea', ed);
    let source = false;
    const sync = () => { ta.value = source ? ta.value : area.innerHTML; };
    area.addEventListener('input', sync);
    $$('[data-cmd]', ed).forEach(b => b.addEventListener('click', () => {
      area.focus();
      if (b.dataset.cmd === 'createLink') { const u = prompt('Link address (e.g. /sets/151 or https://â€¦)'); if (u) document.execCommand('createLink', false, u); }
      else document.execCommand(b.dataset.cmd, false, b.dataset.val ? `<${b.dataset.val}>` : null);
      sync();
    }));
    $('[data-source]', ed).addEventListener('click', () => {
      source = !source;
      if (source) { ta.value = area.innerHTML; ta.hidden = false; ta.classList.add('source'); area.hidden = true; }
      else { area.innerHTML = ta.value; ta.hidden = true; area.hidden = false; }
    });
    const img = $('[data-editor-image]', ed);
    if (img) img.addEventListener('change', async () => {
      const r = await upload(img.files[0], 'page');
      if (r) { area.focus(); document.execCommand('insertHTML', false, `<img src="${r.url}" alt="">`); sync(); }
    });
    ed.closest('form').addEventListener('submit', () => { if (!source) ta.value = area.innerHTML; });
  });

  // photo uploads
  async function upload(file, kind) {
    if (!file) return null;
    const fd = new FormData(); fd.append('file', file); fd.append('kind', kind); fd.append('csrf', window.CSRF);
    const res = await fetch('/admin/upload', {method: 'POST', body: fd});
    const j = await res.json();
    if (j.error) { alert(j.error); return null; }
    return j;
  }
  $$('[data-upload]').forEach(inp => inp.addEventListener('change', async () => {
    const r = await upload(inp.files[0], inp.dataset.upload);
    if (!r) return;
    const target = inp.closest('form').querySelector(`[name="${inp.dataset.target}"]`);
    if (target) target.value = inp.dataset.upload === 'page' ? r.url : r.path;
    const prev = $('[data-photo-preview]');
    if (prev && inp.dataset.upload === 'product') { prev.src = r.url; prev.hidden = false; }
  }));

  // copy product photos to the server, 25 at a time
  const start = $('[data-images-start]'), stop = $('[data-images-stop]');
  if (start) {
    let running = false, done = 0, total = 0;
    const box = $('[data-progress]'), bar = $('[data-bar]'), txt = $('[data-progress-text]');
    async function step() {
      if (!running) return;
      const fd = new FormData(); fd.append('csrf', window.CSRF);
      let j;
      try { j = await (await fetch('/admin/tools/images', {method: 'POST', body: fd})).json(); } catch { txt.textContent = 'Connection dropped. Press Start to resume.'; running = false; start.hidden = false; stop.hidden = true; return; }
      done += j.done; if (!total) total = j.remaining + j.done;
      bar.style.width = (total ? Math.round(100 * (total - j.remaining) / total) : 100) + '%';
      txt.textContent = `${(total - j.remaining).toLocaleString()} of ${total.toLocaleString()} photos handled Â· ${j.remaining.toLocaleString()} left`;
      if (j.remaining > 0 && (j.done + j.failed) > 0) setTimeout(step, 200);
      else { running = false; start.hidden = false; stop.hidden = true; txt.textContent += j.remaining ? '' : ' Â· Finished.'; }
    }
    start.addEventListener('click', () => { running = true; box.hidden = false; start.hidden = true; stop.hidden = false; step(); });
    stop.addEventListener('click', () => { running = false; start.hidden = false; stop.hidden = true; start.textContent = 'Resume'; });
  }
})();
